new_string:
if (gnd && jGnd) {
  addVia(gnd, jGnd);
  add(gnd, jGnd, { x: jGnd.x - 40, y: jGnd.y }, 14, 'In1.Cu');
}
if (vcc && jVcc) {
  addVia(vcc, jVcc);
  add(vcc, jVcc, { x: jVcc.x - 40, y: jVcc.y }, 14, 'In2.Cu');
  add(vcc, { x: jVcc.x - 40, y: jVcc.y }, { x: jVcc.x - 40, y: vccSpineY }, 14, 'In2.Cu');
