fanTop(lmOut, pw('Rf3', 2), jLm, 'In2.Cu', 90, 2680);
fanBot(buckOut, pw('CBO', 1), jBk, 'In2.Cu', 2760);
// B：上 LM555 / 下 VOUT + DISCH（不同 col，H-first）
fanTop(out555, pw('RLED', 1), j555, 'B.Cu', 130, 2640);
fanBot(vout0, pw('REG1', 3), jV0, 'B.Cu', 2700);
fanBot(disch, pw('RA', 2), jDs, 'B.Cu', 2780);
